import Foundation
import OSLog
let logger = Logger(subsystem: "example", category: "load")
func load() -> Data? {
    do { return try Data(contentsOf: URL(fileURLWithPath: "/data/items")) }
    catch { logger.error("Load failed: \(error)"); return nil }
}
func show() { guard let data = load() else { return }; consume(data) }

